pygments.formatters.irc.ircformat:
def ircformat(color, text):
    if len(color) < 1:
        return text
    add = sub = ''
    if '_' in color:
        add += '\x1d'
        sub = '\x1d' + sub
        color = color.strip('_')
    if '*' in color:
        add += '\x02'
        sub = '\x02' + sub
        color = color.strip('*')
    if len(color) > 0:
        add += '\x03' + str(IRC_COLOR_MAP[color]).zfill(2)
        sub = '\x03' + sub
    return add + text + sub

pygments.lexers.__init__.get_lexer_for_m:
def get_lexer_for_mimetype(_mime, **options):
    """
    Return a `Lexer` subclass instance that has `mime` in its mimetype
    list. The lexer is given the `options` at its instantiation.

    Will raise :exc:`pygments.util.ClassNotFound` if not lexer for that mimetype
    is found.
    """
    for (modname, name, _, _, mimetypes) in LEXERS.values():
        if _mime in mimetypes:
            if name not in _lexer_cache:
                _load_lexers(modname)
            return _lexer_cache[name](**options)
    for cls in find_plugin_lexers():
        if _mime in cls.mimetypes:
            return cls(**options)
    raise ClassNotFound(f'no lexer for mimetype {_mime!r} found')

pygments.lexers._scilab_builtins.extract:
def extract_completion(var_type):
    s = subprocess.Popen(['scilab', '-nwni'], stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    output = s.communicate(f'fd = mopen("/dev/stderr", "wt");\nmputl(strcat(completion("", "{var_type}"), "||"), fd);\nmclose(fd)\n')
    if '||' not in output[1]:
        raise Exception(output[0])
    text = output[1].strip()
    if text.startswith('Error: unable to open display \n'):
        text = text[len('Error: unable to open display \n'):]
    return text.split('||')

pygments.lexers.__init__.find_lexer_clas:
def find_lexer_class_by_name(_alias):
    """
    Return the `Lexer` subclass that has `alias` in its aliases list, without
    instantiating it.

    Like `get_lexer_by_name`, but does not instantiate the class.

    Will raise :exc:`pygments.util.ClassNotFound` if no lexer with that alias is
    found.

    .. versionadded:: 2.2
    """
    if not _alias:
        raise ClassNotFound(f'no lexer for alias {_alias!r} found')
    for (module_name, name, aliases, _, _) in LEXERS.values():
        if _alias.lower() in aliases:
            if name not in _lexer_cache:
                _load_lexers(module_name)
            return _lexer_cache[name]
    for cls in find_plugin_lexers():
        if _alias.lower() in cls.aliases:
            return cls
    raise ClassNotFound(f'no lexer for alias {_alias!r} found')

pygments.lexers._sourcemod_builtins.get_:
def get_version():
    f = opener.open('http://docs.sourcemod.net/api/index.php')
    r = re.compile('SourceMod v\\.<b>([\\d\\.]+(?:-\\w+)?)</td>')
    for line in f:
        m = r.search(line.decode())
        if m is not None:
            return m.groups()[0]
    raise ValueError('No version in api docs')

pygments.formatters.latex._get_ttype_nam:
def _get_ttype_name(ttype):
    fname = STANDARD_TYPES.get(ttype)
    if fname:
        return fname
    aname = ''
    while fname is None:
        aname = ttype[-1] + aname
        ttype = ttype.parent
        fname = STANDARD_TYPES.get(ttype)
    return fname + aname

pygments.lexers.__init__.guess_lexer_for:
def guess_lexer_for_filename(_fn, _text, **options):
    """
    As :func:`guess_lexer()`, but only lexers which have a pattern in `filenames`
    or `alias_filenames` that matches `filename` are taken into consideration.

    :exc:`pygments.util.ClassNotFound` is raised if no lexer thinks it can
    handle the content.
    """
    fn = basename(_fn)
    primary = {}
    matching_lexers = set()
    for lexer in _iter_lexerclasses():
        for filename in lexer.filenames:
            if _fn_matches(fn, filename):
                matching_lexers.add(lexer)
                primary[lexer] = True
        for filename in lexer.alias_filenames:
            if _fn_matches(fn, filename):
                matching_lexers.add(lexer)
                primary[lexer] = False
    if not matching_lexers:
        raise ClassNotFound(f'no lexer for filename {fn!r} found')
    if len(matching_lexers) == 1:
        return matching_lexers.pop()(**options)
    result = []
    for lexer in matching_lexers:
        rv = lexer.analyse_text(_text)
        if rv == 1.0:
            return lexer(**options)
        result.append((rv, lexer))

    def type_sort(t):
        return (t[0], primary[t[1]], t[1].priority, t[1].__name__)
    result.sort(key=type_sort)
    return result[-1][1](**options)

pygments.lexers.erlang.gen_elixir_string:
def gen_elixir_string_rules(name, symbol, token):
    states = {}
    states['string_' + name] = [(f'[^#{symbol}\\\\]+', token), include('escapes'), ('\\\\.', token), (f'({symbol})', bygroups(token), '#pop'), include('interpol')]
    return states
